function getStoryboardChunkOutputFormatTemplate() {
  return storyboard_output_format_template_zh;
}
function fillStoryboardOutputFormatTemplate(template, chunkSeconds, maxChars, expectedChunkCount) {
  const approxChinese = Math.floor(maxChars / 1.8);
  const needMultiShotsHint = chunkSeconds >= 10 ? `\u5F53 chunk_seconds \u2265 10 \u79D2\uFF08\u4F8B\u5982 ${chunkSeconds} \u79D2\uFF09\u65F6\uFF0C**\u9ED8\u8BA4\u5FC5\u987B\u4F7F\u7528\u591A\u955C\u5934 chunk\uFF08shots \u6570\u7EC4\u7ED3\u6784\uFF09**\uFF1A
  - \u6BCF\u4E2A chunk \u81F3\u5C11\u62C6\u6210 2 \u4E2A\u955C\u5934\uFF0C\u901A\u5E38\u63A8\u8350 2\u20134 \u4E2A\u955C\u5934\uFF1B
  - \u6BCF\u4E2A\u955C\u5934\u7684 chunk_seconds \u7EA6\u4E3A 3\u20136 \u79D2\uFF08\u53EF\u6839\u636E\u8282\u594F\u5FAE\u8C03\uFF09\uFF1B
  - **\u9664\u975E\u7528\u6237\u5728\u63D0\u793A\u4E2D\u660E\u786E\u8981\u6C42\u300C\u6301\u7EED\u957F\u955C\u5934 / \u4E00\u955C\u5230\u5E95\u300D**\uFF0C\u5426\u5219\u4E0D\u8981\u4F7F\u7528\u5355\u955C\u5934\u6241\u5E73\u7ED3\u6784\uFF08\u4E0D\u8981\u53EA\u7528 video_description \u4E00\u4E2A\u5B57\u6BB5\u8868\u793A\u6574\u6BB5 ${chunkSeconds} \u79D2\u955C\u5934\uFF09\u3002` : `\u5F53 chunk_seconds \u4E3A ${chunkSeconds} \u79D2\u65F6\uFF0C\u53EF\u4EE5\u6839\u636E\u5185\u5BB9\u8282\u594F\u9009\u62E9\u5355\u955C\u5934\u6216\u591A\u955C\u5934\uFF1A\u63A8\u8350 1\u20132 \u4E2A\u955C\u5934\uFF0C\u6839\u636E\u753B\u9762\u53D8\u5316\u548C\u8282\u594F\u7075\u6D3B\u62C6\u5206\u3002`;
  const durationHint = expectedChunkCount != null && expectedChunkCount > 0 ? `
\u3010\u65F6\u957F\u4E0E\u6570\u91CF\u3011\u671F\u671B\u603B\u65F6\u957F **${expectedChunkCount * chunkSeconds} \u79D2**\uFF0C\u6BCF\u6BB5 ${chunkSeconds} \u79D2\u3002\u8BF7**\u6070\u597D**\u751F\u6210 **${expectedChunkCount} \u4E2A** chunk\uFF0C**\u4E0D\u5F97\u8D85\u8FC7**\u8BE5\u6570\u91CF\uFF0C\u5426\u5219\u603B\u65F6\u957F\u4F1A\u8D85\u51FA\u7528\u6237\u671F\u671B\u3002
` : "";
  return template.replace(/\{\{chunk_seconds\}\}/g, String(chunkSeconds)).replace(/\{\{maxChars\}\}/g, String(maxChars)).replace(/\{\{expectedChunkCount\}\}/g, String(expectedChunkCount ?? "")).replace(/\{\{approxChinese\}\}/g, String(approxChinese)).replace(/\{\{needMultiShotsHint\}\}/g, needMultiShotsHint).replace(/\{\{durationHint\}\}/g, durationHint);
}
function getStoryboardChunkOutputFormat(chunkSeconds, maxChars, expectedChunkCount) {
  return fillStoryboardOutputFormatTemplate(
    getStoryboardChunkOutputFormatTemplate(),
    chunkSeconds,
    maxChars,
    expectedChunkCount
  );
}
