function getArticlesParamsForSubtype(outlineType) {
  if (outlineType === "story-novel") {
    return [
      "genre",
      "pov",
      "writing_style",
      "pacing",
      "length",
      "setting",
      "main_characters",
      "conflict",
      "ending_type",
      "themes"
    ];
  }
  if (outlineType === "academic-paper") {
    return [
      "discipline",
      "paper_type",
      "paper_structure",
      "research_question",
      "methodology",
      "data_sources",
      "citation_style",
      "keywords",
      "contribution",
      "length"
    ];
  }
  return ["motivation", "stance", "tone", "targetAudience", "depth", "length", "key_elements"];
}
